import numpy as np
import pandas as pd
import pytest
from astropy.time import Time
from spacepy import pycdf

from swxsoc_reach import _test_files_directory
from swxsoc_reach.calibration.legacy import (
    LEGACY_L2_SHARED_VARIABLES,
    add_legacy_l1_variables,
    build_legacy_l2_swxdata,
    legacy_to_udl_frame,
    process_legacy_day,
    re_to_km,
    set_legacy_global_attributes,
)
from swxsoc_reach.calibration.transform import build_swxdata
from swxsoc_reach.io.file_tools import read_legacy_pipeline_day

# Fixtures generated by experiments/create-legacy-test-files.ipynb
LEGACY_DAY = Time("2026-08-01")
LEGACY_CSV = _test_files_directory / "reach.20260801.vid-101.l1b.v3.csv"
LEGACY_L1_CDF = _test_files_directory / "reach_all_l1_5s_20260801_v1.0.0.cdf"
LEGACY_L2_CDF = _test_files_directory / "reach_all_l2_5s_20260801_v1.0.0.cdf"
N_RECORDS = 3

L1_ONLY_VARIABLES = {
    "dose_rate",
    "hk_temperature",
    "hk_15v_monitor",
    "hk_5v_monitor",
    "hk_3_3v_monitor",
    "lm",
}
L2_ONLY_VARIABLES = {
    "inv_lat",
    "blocal",
    "bmin",
    "mlt",
    "k_sqrt",
    "hmin",
    "alpha",
    "alpha_eq",
    "region_code",
    "orbit_status",
    "proton_flux",
    "electron_flux",
    "species",
}
SHARED_VARIABLES = {"Epoch", *LEGACY_L2_SHARED_VARIABLES}


def _cdf_variables(path):
    with pycdf.CDF(str(path)) as cdf:
        return set(cdf.keys())


def _cdf_global(path, name):
    with pycdf.CDF(str(path)) as cdf:
        return str(cdf.attrs[name][0])


@pytest.fixture
def udl_frame():
    df = read_legacy_pipeline_day(data_dir=_test_files_directory, day=LEGACY_DAY)
    return legacy_to_udl_frame(df)


@pytest.fixture
def l1_data(udl_frame):
    data = build_swxdata(udl_frame)
    add_legacy_l1_variables(data, udl_frame)
    set_legacy_global_attributes(data)
    return data


def test_re_to_km_keeps_fill_values():
    result = re_to_km(pd.Series([1.0, -1e31, 0.5]))
    np.testing.assert_allclose(result, [6371.2, -1e31, 3185.6])


def test_legacy_to_udl_frame_one_row_per_dosimeter(udl_frame):
    assert len(udl_frame) == 2 * N_RECORDS
    assert set(udl_frame["idSensor"]) == {"REACH-101"}
    assert set(udl_frame["descriptor"]) == {"LEGACY"}


def test_add_legacy_l1_variables(l1_data):
    assert L1_ONLY_VARIABLES - {"dose_rate"} <= set(l1_data.support)
    assert not (L2_ONLY_VARIABLES & set(l1_data.support))
    assert l1_data.meta["Data_level"] == "L1>Level 1"
    assert l1_data.meta["Logical_source"] == "reach_all_l1_5s"


def test_build_legacy_l2_swxdata(l1_data, udl_frame):
    l1_support_before = set(l1_data.support)
    l2_data = build_legacy_l2_swxdata(l1_data, udl_frame)

    assert set(l2_data.support) == set(LEGACY_L2_SHARED_VARIABLES) | L2_ONLY_VARIABLES
    assert len(l2_data.timeseries) == len(l1_data.timeseries) == N_RECORDS
    assert l2_data.meta["Data_level"] == "L2>Level 2"
    assert l2_data.meta["Logical_source"] == "reach_all_l2_5s"
    assert l2_data.meta["Logical_file_id"] == "reach_all_l2_5s_20260801_v1.0.0"
    for attr in ("Data_version", "Source_pipeline", "Parents"):
        assert l2_data.meta[attr] == l1_data.meta[attr]

    # The L1 object is unchanged and the shared arrays are copies
    assert set(l1_data.support) == l1_support_before
    assert l2_data.support["lat"] is not l1_data.support["lat"]
    np.testing.assert_array_equal(
        l2_data.support["lat"].data, l1_data.support["lat"].data
    )


def test_build_legacy_l2_swxdata_time_mismatch(l1_data, udl_frame):
    first_time = udl_frame["obTime"].iloc[0]
    with pytest.raises(ValueError, match="Time axis mismatch"):
        build_legacy_l2_swxdata(l1_data, udl_frame[udl_frame["obTime"] != first_time])


def test_process_legacy_day(tmp_path):
    output_files = process_legacy_day(
        LEGACY_DAY, _test_files_directory, output_dir=tmp_path
    )

    assert isinstance(output_files, list)
    assert [p.name for p in output_files] == [LEGACY_L1_CDF.name, LEGACY_L2_CDF.name]
    assert all(p.parent == tmp_path for p in output_files)
    l1_path, l2_path = output_files

    l1_vars = _cdf_variables(l1_path)
    l2_vars = _cdf_variables(l2_path)
    assert SHARED_VARIABLES <= l1_vars
    assert SHARED_VARIABLES <= l2_vars
    assert L1_ONLY_VARIABLES <= l1_vars
    assert L2_ONLY_VARIABLES <= l2_vars
    assert not (L2_ONLY_VARIABLES & l1_vars)
    assert not (L1_ONLY_VARIABLES & l2_vars)

    assert _cdf_global(l1_path, "Data_level") == "L1>Level 1"
    assert _cdf_global(l2_path, "Data_level") == "L2>Level 2"
    assert _cdf_global(l1_path, "Logical_source") == "reach_all_l1_5s"
    assert _cdf_global(l2_path, "Logical_source") == "reach_all_l2_5s"

    with pycdf.CDF(str(l2_path)) as cdf:
        assert len(cdf["Epoch"]) == N_RECORDS
        assert cdf["proton_flux"].shape == (N_RECORDS, 32, 2)
